\section{Introduction}

\subsection{The measurement}
Let $N = pq$ be a balanced semiprime with $p \le q$, and let $T(N)$ denote a running-time surrogate for a factoring algorithm. Fix a bit size $k$ and draw a sample of balanced semiprimes whose smaller factor satisfies $2^{k-1} \le p < 2^{k}$. Write $E(k)$ for the sample mean of $T$ at level $k$. The statistic of interest is the \textbf{across-level log--log slope}
\begin{equation}\label{eq:slope}
\slope_E(k_1,k_2) \;=\; \frac{\log_2 E(k_2) - \log_2 E(k_1)}{k_2 - k_1}, \qquad k_1 < k_2,
\end{equation}
with $\dk = k_2 - k_1$ the \emph{lever arm}. The dataset consists of three channels run on the \emph{same} draws:

\begin{center}
\begin{tabular}{lll}
\toprule
channel & per-instance cost model & measured slope \\
\midrule
trial division & $a\cdot p$ & $0.84$ \\
Pollard rho & $c\cdot \sqrt p$ & $0.52$ \\
Fermat & $\Theta\bigl((q-p)^2/p\bigr)$ & $0.50$ \\
\bottomrule
\end{tabular}
\end{center}

We argue that all three readings need revision, and that the corrections are theorems.

\subsection{Conventions}
$\log_2$ is the binary logarithm and $2^{x}$ the real power. All populations are finite samples of size $n \ge 1$ and $\E$ denotes the unweighted empirical mean, $\E[f] = n^{-1}\sum_{i=1}^{n} f(i)$.

\section{The two-point slope reads a pure power exactly}

\begin{definition}[Two-point log--log slope]
For $E : \N \to \R$ and $k_1 \ne k_2$, define $\slope_E(k_1,k_2)$ by \eqref{eq:slope}.
\end{definition}

\begin{theorem}[Exact recovery of a pure power law]\label{thm:pure}
Let $C > 0$, $\alpha \in \R$ and $E(k) = C\cdot 2^{\alpha k}$. Then $\slope_E(k_1,k_2) = \alpha$ for every $k_1 \ne k_2$.
\end{theorem}

\begin{proof}
$\log_2 E(k) = \log_2 C + \alpha k$, so the numerator of \eqref{eq:slope} equals $\alpha(k_2-k_1)$ and the constant cancels.
\end{proof}

Theorem~\ref{thm:pure} is the licence for the whole method: an exponent may be measured without ever calibrating an implementation. The rest of the paper quantifies what happens when the power law is only approximate.

\section{Power bands and slope identifiability}

\begin{definition}[Power band]
A function $E:\N\to\R$ obeys a \textbf{power band} with exponent $\alpha$ and constants $c_1,c_2$, written $E\in\PB(\alpha;c_1,c_2)$, when $0 < c_1$ and
\[
c_1\cdot 2^{\alpha k} \;\le\; E(k)\;\le\; c_2\cdot 2^{\alpha k}\qquad\text{for all }k\in\N.
\]
The \textbf{spread} is $c_2/c_1 \ge 1$ and the \textbf{logarithmic spread} is $\sigma = \log_2(c_2/c_1)$.
\end{definition}

Evaluating at $k = 0$ gives $c_1 \le c_2$, and the lower bound gives $E(k) > 0$ for all $k$.

\begin{lemma}[Strip localization]\label{lem:strip}
If $E\in\PB(\alpha;c_1,c_2)$ then $\log_2 c_1 + \alpha k \le \log_2 E(k) \le \log_2 c_2 + \alpha k$ for every $k$.
\end{lemma}

\begin{proof}
Apply the monotone map $\log_2$ to the defining inequalities, using $\log_2(c\cdot 2^{\alpha k}) = \log_2 c + \alpha k$.
\end{proof}

\begin{theorem}[Identifiability]\label{thm:ident}
If $E\in\PB(\alpha;c_1,c_2)$ and $k_1 < k_2$, then
\[
\bigl|\slope_E(k_1,k_2) - \alpha\bigr| \;\le\; \frac{\log_2(c_2/c_1)}{k_2-k_1} \;=\; \frac{\sigma}{\dk}.
\]
\end{theorem}

\begin{proof}
Put $D = \log_2 c_2 - \log_2 c_1 = \sigma$. By Lemma~\ref{lem:strip} at $k_1$ and $k_2$,
\[
\bigl|(\log_2 E(k_2) - \log_2 E(k_1)) - \alpha(k_2-k_1)\bigr| \le D,
\]
since each of the two logarithms lies within $[0,D]$ above the corresponding point of the line $\alpha k + \log_2 c_1$. Dividing by $\dk > 0$ and recognizing the left side as $\dk\,|\slope_E - \alpha|$ completes the proof.
\end{proof}

Theorem~\ref{thm:ident} says: \emph{multiplicative model error enters a two-point exponent measurement divided by the lever arm.} Everything below is an application of it in one of its two directions.

\begin{corollary}[Falsification direction]\label{cor:falsify}
If $E\in\PB(\alpha;c_1,c_2)$, $k_1<k_2$ and $d \le |\slope_E(k_1,k_2)-\alpha|$, then
\[
d\cdot\dk \;\le\; \log_2(c_2/c_1), \qquad\text{equivalently}\qquad \frac{c_2}{c_1}\;\ge\;2^{\,d\,\dk}.
\]
\end{corollary}

\subsection{Sharpness and its converse}

\begin{theorem}[The band is attained]\label{thm:attained}
For every $C>0$, $\alpha\in\R$, $\sigma\ge 0$ and $k_1<k_2$ there exists $E\in\PB(\alpha; C2^{-\sigma}, C)$ with
\[
\slope_E(k_1,k_2) \;=\; \alpha + \frac{\sigma}{\dk}.
\]
\end{theorem}

\begin{proof}
Take $E(k) = C2^{-\sigma}2^{\alpha k}$ for $k \ne k_2$ and $E(k_2) = C\,2^{\alpha k_2}$: the curve saturates the lower endpoint at $k_1$ and the upper endpoint at $k_2$, so the numerator of \eqref{eq:slope} is $\alpha\dk + \sigma$.
\end{proof}

\begin{theorem}[Exponents indistinguishable at short lever arm]\label{thm:indist}
Let $C>0$, $\sigma\ge 0$, $k_1<k_2$ and suppose $\alpha_2 - \alpha_1 = 2\sigma/\dk$. Then there exist $E_1\in\PB(\alpha_1;C2^{-\sigma},C)$ and $E_2\in\PB(\alpha_2;C2^{-\sigma},C)$ with $\slope_{E_1}(k_1,k_2) = \slope_{E_2}(k_1,k_2)$.
\end{theorem}

\begin{proof}
Let $E_1$ saturate the band upward across the lever arm, giving slope $\alpha_1 + \sigma/\dk$ by Theorem~\ref{thm:attained}, and let $E_2$ saturate it downward, giving $\alpha_2 - \sigma/\dk$. The hypothesis makes the two equal.
\end{proof}

Theorem~\ref{thm:indist} is the design bound behind the caveat that within-level fits are confounded: a two-level estimator has resolution exactly $2\sigma/\dk$ and no better.

\section{The dyadic window and the pointwise slope band}

At level $k$ every draw satisfies $2^{k-1}\le p \le 2^{k}$. This confinement eliminates the free constants.

\begin{proposition}[Dyadic-window band]\label{prop:dyadic}
If $C\cdot 2^{\alpha(k-1)} \le E(k) \le C\cdot 2^{\alpha k}$ for all $k$, with $C>0$, then $E \in \PB(\alpha; C2^{-\alpha}, C)$ and the logarithmic spread is exactly $\alpha$.
\end{proposition}

\begin{theorem}[Pointwise slope band]\label{thm:ptband}
Let $s\ge 0$, $a>0$, and suppose the level-$k$ population satisfies $2^{k-1}\le p_k(i)\le 2^{k}$ for all $k,i$, with mean cost $E(k) = a\,\E[p_k^{\,s}]$. Then $E\in\PB(s; a2^{-s},a)$ and, for $k_1<k_2$,
\[
\bigl|\slope_E(k_1,k_2) - s\bigr|\;\le\;\frac{s}{\dk}.
\]
No hypothesis on $a$ is required.
\end{theorem}

\begin{proof}
Monotonicity of $x\mapsto x^{s}$ gives $2^{s(k-1)}\le p_k(i)^{s}\le 2^{sk}$ pointwise; averaging preserves both bounds, so $a2^{s(k-1)}\le E(k)\le a2^{sk}$. Apply Proposition~\ref{prop:dyadic} with $C=a$, $\alpha=s$, then Theorem~\ref{thm:ident}: the logarithmic spread is $s$ and $a$ has cancelled.
\end{proof}

\begin{corollary}[The pointwise linear trial-division model is refuted]\label{cor:trial}
Under the hypotheses of Theorem~\ref{thm:ptband} with $s=1$, $k_1=16$, $k_2=24$,
\[
\slope_E(16,24) \;\ge\; 1 - \tfrac18 \;=\; 0.875 \;>\; 0.84 .
\]
Hence the measured $0.84$ is incompatible with a pointwise cost $a\cdot p$ on a dyadic balanced population, for every $a > 0$.
\end{corollary}

\begin{proposition}[Quantified drift]\label{prop:drift}
If $E\in\PB(1;c_1,c_2)$ and $\slope_E(16,24)\le 0.84$, then $\log_2(c_2/c_1)\ge \tfrac54$, hence $c_2/c_1 \ge 2^{5/4} > 2.36$.
\end{proposition}

\begin{proof}
$|0.84-1| = 0.16$ and $0.16\times 8 = 1.28 \ge 5/4$; apply Corollary~\ref{cor:falsify} and exponentiate. For the numerical claim, $(2^{5/4})^4 = 32 > 2.36^4$.
\end{proof}

\section{Cross-channel rigidity on one population}

The protocol runs all channels on the same draws, so $\E[T_{\mathrm{trial}}]$ and $\E[T_\rho]$ are two functionals of the \emph{same} random variable.

\begin{lemma}[Cauchy--Schwarz for the empirical mean]\label{lem:cs}
For a nonnegative sample, $\bigl(\E[\sqrt f]\bigr)^2 \le \E[f]$.
\end{lemma}

\begin{proof}
$\bigl(\sum_i \sqrt{f(i)}\bigr)^2 \le n\sum_i f(i)$; divide by $n^2$.
\end{proof}

\begin{lemma}[Reverse bound on a window]\label{lem:rev}
If $0 < L \le f(i)\le U$ for all $i$, then $\E[f] \le (U/L)\bigl(\E[\sqrt f]\bigr)^2$.
\end{lemma}

\begin{proof}
$\E[\sqrt f]\ge \sqrt L$, so $(\E[\sqrt f])^2 \ge L$; and $\E[f]\le U = (U/L)\cdot L$.
\end{proof}

\begin{theorem}[Cross-channel bracket]\label{thm:bracket}
Let $a,c>0$ and let the level population satisfy $L \le p(i)\le U$ with $0<L$ and $U\le 2L$. With $T_{\mathrm{trial}} = a\,p$ and $T_\rho = c\sqrt p$ pointwise,
\[
\frac{a}{c^2}\bigl(\E[T_\rho]\bigr)^2 \;\le\; \E[T_{\mathrm{trial}}] \;\le\; 2\frac{a}{c^2}\bigl(\E[T_\rho]\bigr)^2 .
\]
\end{theorem}

\begin{theorem}[Cross-channel rigidity law]\label{thm:rigid}
Let $a,c>0$ and suppose that for every level $k$ the population satisfies $2^{k-1}\le p_k(i)\le 2\cdot 2^{k-1}$, with $E_{\mathrm{trial}}(k) = a\,\E[p_k]$ and $E_\rho(k) = c\,\E[\sqrt{p_k}]$. Then for $k_1<k_2$,
\[
\bigl|\slope_{E_{\mathrm{trial}}}(k_1,k_2) - 2\,\slope_{E_\rho}(k_1,k_2)\bigr| \;\le\; \frac{1}{\dk}.
\]
Both implementation constants cancel exactly.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:bracket} at each level, $g(k) := \log_2 E_{\mathrm{trial}}(k) - 2\log_2 E_\rho(k)$ lies in $[\log_2 K, \log_2 K + 1]$ with $K = a/c^2$. Hence $|g(k_2)-g(k_1)|\le 1$, and $g(k_2)-g(k_1) = \dk\,(\slope_{\mathrm{trial}} - 2\slope_\rho)$ by definition.
\end{proof}

\begin{corollary}[The reported pair is impossible]\label{cor:pair}
Under the hypotheses of Theorem~\ref{thm:rigid} with $k_1=16$, $k_2=24$, one cannot have simultaneously $\slope_{\mathrm{trial}}\le 0.84$ and $\slope_\rho \ge 0.52$: those force a discrepancy of at least $0.20$, whereas the law allows $1/8 = 0.125$.
\end{corollary}

\begin{proposition}[Non-vacuity]\label{prop:witness}
The hypotheses are satisfiable. The one-point population $p_k \equiv 2^{k-1}$ with $a = c = 1$ gives $E_{\mathrm{trial}}(k) = \tfrac12 2^{k}$ and $E_\rho(k) = 2^{-1/2}2^{k/2}$, hence exactly $\slope_{\mathrm{trial}} = 1$ and $\slope_\rho = \tfrac12$, saturating the law with zero slack.
\end{proposition}

\section{The sharp cross-channel constant: Kantorovich and the doubling ray}

Lemma~\ref{lem:rev} discards all interior structure of the window; numerically the extremal populations reach only about $0.0216/\dk$, so Theorem~\ref{thm:rigid} is loose by a factor near $23$. The correct reverse inequality is Kantorovich's.

\begin{theorem}[Kantorovich inequality for empirical means]\label{thm:kant}
If $0 < a \le y(i) \le b$ for all $i$, then $4ab\,\E[y^2] \le (a+b)^2 (\E[y])^2$.
\end{theorem}

\begin{proof}
Pointwise $(y(i)-a)(b-y(i))\ge 0$, i.e.\ $y(i)^2 \le (a+b)y(i) - ab$; averaging gives $\E[y^2] \le (a+b)m - ab$ with $m = \E[y]$. It suffices that $4ab((a+b)m - ab) \le (a+b)^2m^2$, which rearranges to $\bigl((a+b)m - 2ab\bigr)^2 \ge 0$.
\end{proof}

\begin{corollary}[Dyadic Kantorovich]\label{cor:dyadickant}
If $0 < L \le f(i)\le 2L$ for all $i$, then
\[
\E[f] \;\le\; \frac{4+3\sqrt2}{8}\,\bigl(\E[\sqrt f]\bigr)^2 .
\]
\end{corollary}

\begin{proof}
Put $y = \sqrt f$, so $\sqrt L \le y(i) \le \sqrt2\sqrt L$, and apply Theorem~\ref{thm:kant} with $a = \sqrt L$, $b = \sqrt 2\sqrt L$; note $\E[y^2] = \E[f]$ and
\[
\frac{(a+b)^2}{4ab} = \frac{(1+\sqrt2)^2}{4\sqrt2} = \frac{3+2\sqrt2}{4\sqrt2} = \frac{4+3\sqrt2}{8}\approx 1.03033. \qedhere
\]
\end{proof}

\begin{theorem}[Sharpened cross-channel rigidity]\label{thm:rigidsharp}
Under the hypotheses of Theorem~\ref{thm:rigid},
\[
\bigl|\slope_{\mathrm{trial}} - 2\,\slope_\rho\bigr| \;\le\; \frac{\log_2\!\bigl((4+3\sqrt2)/8\bigr)}{\dk}, \qquad \log_2\!\Bigl(\frac{4+3\sqrt2}{8}\Bigr) < 0.044 .
\]
\end{theorem}

\begin{corollary}[Sharp refutation]\label{cor:sharprefute}
At $\dk = 8$ the admissible discrepancy is below $0.0055$, whereas the reported pair demands $0.20$: the measurement misses the sharpened bound by a factor exceeding $36$, against a factor $1.6$ for Theorem~\ref{thm:rigid}.
\end{corollary}

\subsection{The doubling ray}

\begin{definition}
For $t>0$ set $K(t) = \dfrac{(1+2^{t})^{2}}{4\cdot 2^{t}} \ge 1$.
\end{definition}

\begin{theorem}[Doubling-ray bound]\label{thm:doubling}
On a dyadic population, $\E[p^{2t}] \le K(t)\,(\E[p^{t}])^{2}$; consequently, for pointwise costs $a p^{2t}$ and $c p^{t}$ measured on one population,
\[
\bigl|\slope_{2t} - 2\,\slope_{t}\bigr| \;\le\; \frac{\log_2 K(t)}{\dk}.
\]
\end{theorem}

\begin{proposition}
$K(1/2) = (4+3\sqrt2)/8$, so Theorem~\ref{thm:rigidsharp} is the $t = 1/2$ member of the family. Moreover $\log_2 K(t) < 2t^2$ for $0 < t \le 1$, and $\log_2 K(t)\sim t^2\ln 2/4$ as $t \to 0$.
\end{proposition}

\section{General exponent pairs: power-mean rigidity}

\begin{theorem}[Power-mean monotonicity for empirical means]\label{thm:pm}
For a nonnegative sample and $0 < t \le s$, $\bigl(\E[p^{t}]\bigr)^{s/t} \le \E[p^{s}]$.
\end{theorem}

\begin{proof}
Apply $\bigl(n^{-1}\sum_i x_i\bigr)^{r} \le n^{-1}\sum_i x_i^{r}$, valid for $r = s/t \ge 1$ and $x_i\ge 0$ by convexity, to $x_i = p(i)^{t}$.
\end{proof}

\begin{theorem}[Power-mean bracket]\label{thm:pmbracket}
On a dyadic population, with $K = a/c^{s/t}$, $E_A(k) = a\,\E[p_k^{s}]$ and $E_B(k) = c\,\E[p_k^{t}]$,
\[
K\cdot E_B(k)^{s/t} \;\le\; E_A(k)\;\le\; 2^{s}K\cdot E_B(k)^{s/t}.
\]
\end{theorem}

\begin{theorem}[General cross-channel slope law]\label{thm:general}
Under the hypotheses of Theorem~\ref{thm:pmbracket}, for $k_1<k_2$,
\[
\bigl|\,t\cdot\slope_{E_A}(k_1,k_2) - s\cdot\slope_{E_B}(k_1,k_2)\,\bigr| \;\le\; \frac{s\,t}{\dk},
\]
with both implementation constants cancelling.
\end{theorem}

\begin{remark}
Taking $(s,t) = (1,\tfrac12)$ recovers Theorem~\ref{thm:rigid}. The natural guess $(s+t)/(2\dk)$ for the constant is \emph{wrong}; the correct generic constant is $st/\dk$, improvable along the doubling ray $s = 2t$ to $\log_2 K(t)/\dk$.
\end{remark}

\section{Fermat's method: exact gap locality and exponent transfer}

Fermat's method starts at $x = \lceil\sqrt N\rceil$ and terminates at $x = (p+q)/2$, so its step count is the \emph{offset} $(p+q)/2 - \sqrt{pq}$ up to $O(1)$.

\begin{lemma}[Offset identity]\label{lem:offset}
For $p,q\ge 0$, $\dfrac{p+q}{2} - \sqrt{pq} = \dfrac{(\sqrt q - \sqrt p)^2}{2}$.
\end{lemma}

\begin{theorem}[Gap-locality law]\label{thm:gaploc}
For $0 < p \le q$,
\[
\frac{(q-p)^2}{8q}\;\le\;\frac{p+q}{2} - \sqrt{pq}\;\le\;\frac{(q-p)^2}{8p}.
\]
\end{theorem}

\begin{proof}
Write $s = \sqrt p$, $u = \sqrt q$, so $q - p = (u-s)(u+s)$ and the offset is $(u-s)^2/2$ by Lemma~\ref{lem:offset}. Since $0 < s \le u$ we have $4s^2 \le (u+s)^2 \le 4u^2$, whence
\[
\frac{(q-p)^2}{8q} = \frac{(u-s)^2(u+s)^2}{8u^2} \le \frac{(u-s)^2}{2} \le \frac{(u-s)^2(u+s)^2}{8s^2} = \frac{(q-p)^2}{8p}. \qedhere
\]
\end{proof}

Thus Fermat's cost is $\Theta(\mathrm{gap}^2/p)$: a purely local function of the prime gap, so its scaling exponent is a readout of the population's gap distribution rather than a property of the algorithm.

\begin{theorem}[Exponent transfer]\label{thm:transfer}
Suppose the mean gap obeys $G\in\PB(\beta;g_1,g_2)$, the small factor obeys $P\in\PB(1;1,2)$, and $F(k) = G(k)^2/(8P(k))$. Then
\[
F \in \PB\Bigl(2\beta - 1;\ \frac{g_1^2}{16},\ \frac{g_2^2}{8}\Bigr).
\]
In particular $\alpha_{\mathrm{Fermat}} = 2\beta_{\mathrm{gap}} - 1$, with constants composing multiplicatively.
\end{theorem}

\begin{corollary}[Fermat as a gap-exponent meter]\label{cor:gapmeter}
If $|\sigma - (2\beta-1)|\le\varepsilon$ for a measured Fermat slope $\sigma$, then $\bigl|\beta - \tfrac{\sigma+1}{2}\bigr| \le \varepsilon/2$. Applied to $\sigma = 0.50$, this predicts $\beta_{\mathrm{gap}} = 0.75$.
\end{corollary}

A population whose gaps scaled proportionally to $p$ would have $\beta = 1$ and would show a Fermat slope of $1$. The reported $0.50$ therefore says that the sampler's balanced gaps grow like $p^{3/4}$.

\section{Anchoring the rho exponent in a proved threshold}

\begin{theorem}[Storage threshold]\label{thm:storage}
For all $p,m\in\N$: $\;p < m^2 \iff \lfloor\sqrt p\rfloor + 1 \le m$.
\end{theorem}

\begin{proof}
If $m \le \lfloor\sqrt p\rfloor$ then $m^2 \le \lfloor\sqrt p\rfloor^2 \le p$; conversely $p < (\lfloor\sqrt p\rfloor+1)^2 \le m^2$.
\end{proof}

\begin{theorem}[Threshold achieves a collision]\label{thm:collision}
For $p \ge 1$ and any finite set $A$ of integers with $|A| \ge \lfloor\sqrt p\rfloor + 1$, there exist distinct pairs of elements of $A$ whose sums agree modulo $p$.
\end{theorem}

So the minimal storage guaranteeing a two-sum collision modulo $p$ is exactly $\lfloor\sqrt p\rfloor + 1$: the birthday exponent $1/2$ is the exponent of a proved threshold.

\begin{proposition}\label{prop:sandwich}
For $p \ge 1$, $\sqrt p \le \lfloor\sqrt p\rfloor + 1 \le 2\sqrt p$; hence the threshold obeys a power band with exponent $1/2$ and spread at most $2$, and Theorem~\ref{thm:ident} identifies its exponent.
\end{proposition}

\begin{theorem}[Certified rho band]\label{thm:rhoband}
If $2^{(k-1)/2}\le E_\rho(k)\le 2^{k/2}$ for all $k$, then $\bigl|\slope_{E_\rho}(16,24) - \tfrac12\bigr| \le \tfrac1{16}$.
\end{theorem}

\begin{theorem}[The measured $0.52$ is realizable]\label{thm:realizable}
There exists $E$ satisfying $2^{(k-1)/2}\le E(k)\le 2^{k/2}$ at every level with $\slope_E(16,24) = 0.52$ exactly.
\end{theorem}

\begin{proof}
Take $E(k) = 2^{(k-1)/2}$ for $k \ne 24$ and $E(24) = 2^{11.66}$; admissibility at $k = 24$ needs $11.5 \le 11.66 \le 12$, and the slope is $(11.66 - 7.5)/8 = 0.52$.
\end{proof}

The rho measurement is therefore \emph{non-refuting}: it lies inside the certified band and is attained by an admissible curve, but only because the window slack is spent almost entirely at the two endpoints.

\section{Cost truncation cannot explain the deficit}

\begin{definition}
For $B>0$ the truncated per-instance cost at level $k$ is $\tau_B(k,p) = \min\bigl(p,\; B\cdot 2^{k}\bigr)$.
\end{definition}

\begin{theorem}[Truncated band]\label{thm:trunc}
On a dyadic population, $E(k) = a\,\E[\tau_B(k,p_k)]$ obeys $E\in\PB\bigl(1;\,a\min(\tfrac12,B),\,a\min(1,B)\bigr)$.
\end{theorem}

\begin{proposition}[Uniform spread]\label{prop:truncspread}
$\dfrac{\min(1,B)}{\min(1/2,B)} \le 2$ for every $B>0$.
\end{proposition}

\begin{theorem}[Truncation no-go]\label{thm:nogo}
For every $B>0$, $\slope_E(16,24)\ge 0.875$; equivalently the deficit produced by truncation is strictly below $1/8$. No truncation level reproduces the reported $0.84$.
\end{theorem}

\begin{theorem}[Full truncation gives zero deficit]\label{thm:fulltrunc}
If $B \le 1/2$ the bound binds on every draw, $\tau_B(k,p) = B2^{k}$ identically, $E(k) = aB\cdot 2^{k}$ is a pure power, and $\slope_E = 1$ exactly.
\end{theorem}

Truncation removes mass but cannot tilt the window by more than the window's own width: the compression must come from the $p$-distribution, not from the cost accounting.

\section{The shape-drift identity}

Write each level in normalized form $p_k(i) = 2^{k}u_k(i)$ with $u_k(i) > 0$; for a dyadic sampler $u_k(i)\in[\tfrac12,1]$.

\begin{definition}[Shape moment]
$M_s(k) = \E\bigl[u_k^{\,s}\bigr]$. For a scale-invariant sampler $M_s$ is independent of $k$.
\end{definition}

\begin{lemma}[Exact factorization]\label{lem:factor}
With pointwise cost $a\,p^{s}$, $\;E(k) = a\,\E\bigl[(2^{k}u_k)^{s}\bigr] = \bigl(a\,M_s(k)\bigr)\cdot 2^{sk}$.
\end{lemma}

\begin{theorem}[Shape-drift identity]\label{thm:shape}
For $a>0$, $u_k(i)>0$ and $k_1<k_2$,
\[
\slope_E(k_1,k_2) \;=\; s \;+\; \frac{\log_2\bigl(M_s(k_2)/M_s(k_1)\bigr)}{\dk}.
\]
No hypothesis on the window is needed, and the implementation constant $a$ cancels.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:factor}, $\log_2 E(k) = \log_2 a + \log_2 M_s(k) + sk$; difference and divide by $\dk$.
\end{proof}

\begin{corollary}[Compression is equivalent to shape decrease]\label{cor:compress}
$\slope_E(k_1,k_2) < s \iff M_s(k_2) < M_s(k_1)$, and dually. A scale-invariant sampler gives $\slope_E = s$ exactly, with no tolerance at all.
\end{corollary}

\begin{corollary}[Inversion and the prediction]\label{cor:predict}
A measured deficit $d = s - \slope_E$ pins the drift exactly, $M_s(k_1)/M_s(k_2) = 2^{d\dk}$. At $s = 1$, $k_1 = 16$, $k_2 = 24$, the reported $0.84$ forces
\[
\frac{M_1(16)}{M_1(24)} = 2^{1.28}\approx 2.428 \;\ge\; 2.36 .
\]
\end{corollary}

\begin{theorem}[A dyadic sampler cannot drift that far]\label{thm:dyadicdrift}
If $u_k(i)\in[\tfrac12,1]$ for all $k,i$, then $M_1(k)\in[\tfrac12,1]$, so $M_1(k_1)/M_1(k_2)\le 2 < 2^{1.28}$ and $\slope_E(16,24)\ge 0.875$.
\end{theorem}

Thus the measurement also refutes the dyadic window itself, independently of the truncation route.

\begin{theorem}[The mechanism is sufficient]\label{thm:realize084}
Let $u_k \equiv 2^{-0.16k}$. Then with $s = 1$ the mean cost is the pure power $E(k) = a\,2^{0.84k}$, so $\slope_E(16,24) = 0.84$ exactly and $M_1(16)/M_1(24) = 2^{1.28}$.
\end{theorem}

\section{Discussion}

\subsection{The status of each measurement}
\begin{itemize}[leftmargin=1.4em]
\item \textbf{Pollard rho $(0.52)$}: non-refuting. Inside the certified band $1/2\pm 1/16$ (Theorem~\ref{thm:rhoband}) and attained by an admissible curve (Theorem~\ref{thm:realizable}); since the anchoring exponent is that of a proved threshold (Theorems~\ref{thm:storage}--\ref{thm:collision}), this is a genuine replication.
\item \textbf{Fermat $(0.50)$}: not an algorithmic exponent. By Theorem~\ref{thm:gaploc} the cost is $\Theta(\mathrm{gap}^2/p)$, so by Theorem~\ref{thm:transfer} and Corollary~\ref{cor:gapmeter} the measurement reports $\beta_{\mathrm{gap}} = 3/4$.
\item \textbf{Trial division $(0.84)$}: refuting, in four independent senses --- Corollary~\ref{cor:trial}, Corollary~\ref{cor:pair} sharpened by Corollary~\ref{cor:sharprefute}, Theorem~\ref{thm:nogo}, and Corollaries~\ref{cor:compress}--\ref{cor:predict} with Theorem~\ref{thm:dyadicdrift}.
\end{itemize}

\subsection{Two directions of one inequality}
Everything is Theorem~\ref{thm:ident} used twice. Forwards it is a guarantee: bounded model error plus a long lever arm identifies an exponent. Backwards (Corollary~\ref{cor:falsify}) it is a refutation engine: an anomalous slope certifies a quantified drift of the constants. A protocol reporting exponents without a lever arm and a model spread can make neither statement.

\subsection{Why co-measurement matters}
Two channels run on the same draws are two functionals of one random variable, and their expectations are yoked by an inequality. The resulting constant-free law $|t\slope_s - s\slope_t| \le st/\dk$ constrains the reported numbers with no knowledge of the implementations. The design principle is: \emph{always co-measure}, because the pair is more rigid than the sum of its parts.

\subsection{On honesty about resolution}
Theorem~\ref{thm:indist} says that at lever arm $\dk$ inside a window of spread $2^{\sigma}$, exponents separated by less than $2\sigma/\dk$ are not separable by any two-point estimator. Here ($\sigma = s = 1$, $\dk = 8$) the resolution is $0.25$; within-level fits, effectively $\dk\lesssim 1$, have resolution $\gtrsim 2$ and are uninformative about the exponent.

\subsection{Limitations}
The cost models are surrogates. Constant-factor effects within a level are absorbed into the band spread; where they exceed the modelled spread the refutations weaken, but Corollary~\ref{cor:falsify} quantifies exactly how much spread a rescue requires. Elliptic-curve and sieve channels have subexponential costs in $\log p$, so the power-band formalism does not apply to them without modification.

\section{Future directions}

\begin{enumerate}[leftmargin=1.6em]
\item \textbf{Slope identifiability.} Multiplicative model error enters a two-point exponent measurement divided by the lever arm: $|\slope - \alpha| \le \log_2(c_2/c_1)/\dk$. Everything else is a consequence of this one inequality, used in both directions.
\item \textbf{Pollard rho is the birthday law.} The certified band at $\dk = 8$ is $1/2\pm 1/16$, and an explicit admissible curve has slope exactly $0.52$; the measurement is non-refuting, and its exponent is anchored in the proved threshold $\lfloor\sqrt p\rfloor + 1$.
\item \textbf{Fermat is a gap meter.} The transfer law $\alpha_{\mathrm{Fermat}} = 2\beta_{\mathrm{gap}} - 1$ was proved and confirmed numerically ($0.985$ against $2(0.999)-1$). Inverting the reported $0.50$ predicts $\beta_{\mathrm{gap}} = 0.75$.
\item \textbf{The trial-division $0.84$ is a refutation.} A pointwise $a\cdot p$ cost on any dyadic population forces slope $>0.875$; matching $0.84$ requires a constant drift of at least $2^{5/4} > 2.36$.
\item \textbf{Cross-channel rigidity.} Cauchy--Schwarz plus the dyadic window give $|\slope_{\mathrm{trial}} - 2\slope_\rho| \le 1/\dk$ with both constants cancelling; the reported pair violates it, and an explicit witness shows the hypotheses are satisfiable.
\item \textbf{Power-mean rigidity.} For general $0 < t \le s$ the law is $|t\slope_A - s\slope_B| \le st/\dk$; the conjectured constant $(s+t)/(2\dk)$ was wrong.
\item \textbf{Sharpness and its converse.} The identifiability band is attained, and two exponents differing by $2\sigma/\dk$ admit admissible populations with identical two-point slopes.
\item \textbf{Sharp constants.} Kantorovich gives $\log_2((4+3\sqrt2)/8) < 0.044$ in place of $1$, and along the doubling ray $K(t) = (1+2^t)^2/(4\cdot 2^t)$ with $\log_2 K(t) < 2t^2$. Open: the sharp constant off the doubling ray.
\item \textbf{Direct measurement of the shape drift.} The identity turns $0.84$ into the exact prediction $M_1(16)/M_1(24) = 2^{1.28}$; measuring the normalized moments of the actual draws would settle in one computation whether the anomaly is in the sampler or in the fit.
\item \textbf{Subexponential channels.} A band formalism in $\log\log$ rather than $\log$ is needed for elliptic-curve and sieve costs; the analogue of lever-arm division is not yet known.
\end{enumerate}

\section{Conclusion}

Measuring a scaling exponent from a handful of problem sizes is a legitimate inference provided one is explicit about a single number: the ratio of the model's multiplicative uncertainty to the lever arm. Once that number is written down, the three reported factoring slopes cease to be a table of approximate confirmations and become three distinct epistemic objects --- a genuine replication anchored in a proved threshold, a thermometer reading the gap exponent of the population, and a robust refutation which resolves, by an exact identity, into a single directly measurable claim about how the sampler's normalized factor distribution drifts with bit size. The broader lesson is that co-measurement is rigidity: running several cost channels on one population yields constraints in which every implementation constant cancels, strong enough to declare a reported pair of exponents impossible.

